export function normalizeArabicAssessmentPrompt(text: string): string {
  if (!text) return "";
  return text
    .trim()
    .replace(/[\s\u200B\u200C\u200D\uFEFF]+/g, " ")
    .replace(/[؟?.,!:\-\(\)]/g, "")
    .replace(/[أإآا]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ى/g, "ي")
    .trim()
    .toLowerCase();
}

export interface AssessmentBadgeData {
  isAssessment: boolean;
  isDirect: boolean;
  label: string;
}

export function checkIsAssessmentQuestion(q: any): AssessmentBadgeData | null {
  if (!q) return null;

  // 1. Direct object properties
  const isDirect = Boolean(
    q.is_official_assessment === true ||
    q.isOfficialAssessment === true ||
    q.source_type === "OFFICIAL_ASSESSMENT" ||
    q.sourceType === "OFFICIAL_ASSESSMENT" ||
    q.source_classification === "OFFICIAL_ASSESSMENT_NEAR_LITERAL" ||
    q.source_classification === "OFFICIAL_ASSESSMENT_VERIFIED_ADDED" ||
    q.sourceClassification === "OFFICIAL_ASSESSMENT_NEAR_LITERAL" ||
    q.sourceClassification === "OFFICIAL_ASSESSMENT_VERIFIED_ADDED"
  );

  const isAdapted = Boolean(
    q.source_type === "ASSESSMENT_ADAPTED" ||
    q.sourceType === "ASSESSMENT_ADAPTED" ||
    q.source_classification === "ASSESSMENT_SIMILAR_WORDING" ||
    q.sourceClassification === "ASSESSMENT_SIMILAR_WORDING"
  );

  const citation = q.assessment_citation || q.assessmentCitation;
  const asrc = q.assessment_source || q.assessmentSource;
  const page = asrc?.pdf_page || asrc?.page;

  if (isDirect) {
    const label = citation || (page ? `تقييمات الوزارة - ص ${page}` : "تقييمات الوزارة ⭐");
    return { isAssessment: true, isDirect: true, label };
  }

  if (isAdapted) {
    const label = citation || (page ? `فكرة تقييمات - ص ${page}` : "تقييمات معتمدة 📘");
    return { isAssessment: true, isDirect: false, label };
  }

  if (citation) {
    const isDir = citation.includes("رسمية") || citation.includes("⭐");
    return { isAssessment: true, isDirect: isDir, label: citation };
  }

  if (Array.isArray(q.tags) && q.tags.some((t: string) => typeof t === "string" && (t.includes("تقييم") || t.includes("وزارة")))) {
    return { isAssessment: true, isDirect: true, label: "تقييمات الوزارة ⭐" };
  }

  // 2. Lookup by normalized prompt
  const pNorm = normalizeArabicAssessmentPrompt(q.prompt || q.statement || q.questionText || "");
  if (pNorm && ASSESSMENT_PROMPTS_MAP[pNorm]) {
    const item = ASSESSMENT_PROMPTS_MAP[pNorm];
    return {
      isAssessment: true,
      isDirect: item.d === 1,
      label: item.c,
    };
  }

  return null;
}
